// Shared pieces of the React auth pages generated by `lila auth --react`.
import type { InputHTMLAttributes, ReactNode } from "react";
import { useT } from "@lila";

export interface Provider {
  key: string;
  name: string;
  href: string;
}

export interface SessionUser {
  user_id: number;
  email: string;
  name: string;
}

export function AuthCard({ title, subtitle, children }: { title: string; subtitle?: string; children: ReactNode }) {
  return (
    <main className="flex min-h-screen flex-col items-center justify-center bg-slate-50 px-4 py-12 text-slate-800 dark:bg-slate-950 dark:text-slate-100">
      <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-8 shadow-lg dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-6 flex flex-col items-center">
          <img src="/img/lila-128.webp" alt="Lila" width={48} height={48} className="mb-2 rounded-2xl bg-white p-1 shadow-sm" />
          <h1 className="bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-2xl font-black text-transparent">{title}</h1>
          {subtitle && <p className="mt-1 text-xs text-slate-400">{subtitle}</p>}
        </div>
        {children}
      </div>
    </main>
  );
}

interface FieldProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  error?: string;
  aside?: ReactNode;
}

export function Field({ label, error, aside, id, ...input }: FieldProps) {
  return (
    <div>
      <div className="mb-1.5 flex items-center justify-between">
        <label htmlFor={id} className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400">
          {label}
        </label>
        {aside}
      </div>
      <input
        id={id}
        className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 aria-[invalid=true]:border-red-500 dark:border-slate-800 dark:bg-slate-950"
        {...input}
      />
      {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
  );
}

export function Submit({ processing, children }: { processing: boolean; children: ReactNode }) {
  const t = useT();
  return (
    <button
      type="submit"
      disabled={processing}
      className="mt-2 w-full rounded-xl bg-blue-600 py-2.5 text-sm font-semibold text-white shadow-md transition hover:bg-blue-700 disabled:opacity-60"
    >
      {processing ? t("loading", "Loading...") : children}
    </button>
  );
}

export function FormMessage({ error, message }: { error?: string; message?: string }) {
  if (error) return <p role="alert" className="rounded-xl bg-red-50 px-4 py-2 text-sm text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</p>;
  if (message) return <p role="status" className="rounded-xl bg-emerald-50 px-4 py-2 text-sm text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">{message}</p>;
  return null;
}

export function OAuthButtons({ providers }: { providers: Provider[] }) {
  const t = useT();
  if (!providers.length) return null;
  return (
    <>
      <div className="mb-6 flex flex-col gap-2.5">
        {providers.map((provider) => (
          // Full navigation: the OAuth flow leaves the app.
          <a
            key={provider.key}
            href={provider.href}
            className="flex w-full items-center justify-center gap-3 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold shadow-sm hover:bg-slate-50 dark:border-slate-800 dark:bg-slate-900 dark:hover:bg-slate-800"
          >
            {t("continue_with", "Continue with")} {provider.name}
          </a>
        ))}
      </div>
      <div className="relative my-6 flex items-center justify-center">
        <div className="w-full border-t border-slate-200 dark:border-slate-800" />
        <span className="absolute bg-white px-3 text-xs font-bold uppercase tracking-wider text-slate-400 dark:bg-slate-900">
          {t("or_with_email", "Or with email")}
        </span>
      </div>
    </>
  );
}
